import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const attributeJewelsPhysicalScenarios=['crown-install','crystal-install','crown-fate','crystal-fate','crown-decline','crystal-decline','crown-element','crystal-element','crown-other','crystal-other','crown-human','crystal-human','crown-wrong','crystal-wrong','crown-nonhuman','crystal-nonhuman','crown-convert-on','crystal-convert-on','crown-convert-off','crystal-convert-off','crown-training','crystal-training','crown-army-human','crystal-army-human','crown-army-nonhuman','crystal-army-nonhuman'] as const;
export type AttributeJewelsPhysicalScenario=typeof attributeJewelsPhysicalScenarios[number];
export function isAttributeJewelsPhysicalScenario(name:string):name is AttributeJewelsPhysicalScenario{return (attributeJewelsPhysicalScenarios as readonly string[]).includes(name);}
export function jewelMode(name:AttributeJewelsPhysicalScenario){const crown=name.startsWith('crown'),converted=name.includes('-convert-'),wrong=name.endsWith('-wrong')||name.endsWith('-convert-on'),initialEvil=crown?wrong:!wrong,morale=['human','wrong','nonhuman','convert-on','convert-off'].some(s=>name.endsWith('-'+s)),early=['install','fate','decline'].some(s=>name.endsWith('-'+s));return {army:name.includes('-army-'),crown,converted,initialEvil,finalEvil:converted?!initialEvil:initialEvil,morale,early,training:name.endsWith('-training'),card:crown?'a2-p03-r1c2' as const:'a2-p03-r1c3' as const,bonus:crown?1:2,spell:name.endsWith('-other')?crown?'a2-p13-r2c1':'a2-p12-r2c2':crown?'a2-p12-r2c2':'a2-p15-r2c2',follower:name.endsWith('-nonhuman')?'a2-p20-r3c1':'a2-p21-r2c2'};}
/** Actual setup followers, self installation, full turns and optional post-install
 * public conversion. No attachment, faction change, attack or roll is injected. */
export function makeAttributeJewelsPhysicalScenario(name:AttributeJewelsPhysicalScenario,players:{id:string;name:string}[],options:{spell?:string;magic?:number;blood?:boolean;endurance?:number}={}){
 const m=jewelMode(name),spell=options.spell??m.spell;let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.initialEvil?'黒騎士ガーウィン':'大神官ジル',m.finalEvil?'侍大将のシン':'魔導王ガイナス','小妖精のチャム','占星術師のアルセイル'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[a]!.permanent!.magic_level!+=(options.magic??3)-gameStats(s,a).magic_level;s.players[a]!.permanent!.spirit!+=6-gameStats(s,a).spirit;
 if(options.endurance!==undefined)s.players[a]!.permanent!.endurance!+=options.endurance-gameStats(s,a).endurance;
 const keep=[takeCard(s,a,m.card),takeCard(s,a,spell),takeCard(s,a,'a2-p03-r2c3'),takeCard(s,b,'a2-p24-r1c2'),takeCard(s,d,'a2-p02-r2c3')];if(m.army)keep.push(takeCard(s,a,'a2-p05-r2c2'));if(m.morale)keep.push(takeCard(s,a,m.follower));if(m.converted)keep.push(takeCard(s,d,m.finalEvil?'a2-p04-r1c2':'a2-p04-r1c1'));for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(options.blood){takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!=='a2-p01-r1c3');s.deck.unshift('a2-p01-r1c3');}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`JEWEL_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('JEWEL_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('JEWEL_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<500;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('JEWEL_FIXTURE_WINDOW');}
 function start(id:string){act(id,{type:'START_TURN'});settle();act(id,{type:'CHOOSE_DRAW',draw:false});settle();}
 function end(id:string){if(s.phase==='action')act(id,{type:'PASS_ACTION'});if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 for(const id of [a,b,c,d]){if(id===a&&m.morale&&!m.army)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));start(a);if(m.early)return s;act(a,{type:'PLAY_TURN_CARD',cardInstanceId:m.card});settle();end(a);if(m.morale&&!m.converted&&!m.army){start(b);return s;}
 for(const id of [b,c,d]){start(id);if(id===d&&m.converted){act(a,{type:'REVEAL_CHARACTER'});settle();act(d,{type:'PLAY_TURN_CARD',cardInstanceId:m.finalEvil?'a2-p04-r1c2':'a2-p04-r1c1',targetId:a});settle(6);if(s.players[a]!.faction!==(m.finalEvil?'EVIL':'GOOD'))throw Error('JEWEL_CONVERSION');}end(id);}start(a);if(m.morale&&!m.army){end(a);start(b);}return s;
}
